CREATE TYPE council_cycle_status AS ENUM ('open','closed');
CREATE TYPE council_decision_status AS ENUM ('proposed','superseded');
CREATE TYPE council_outcome_status AS ENUM ('verified','inconclusive','unsupported','exception');
CREATE TYPE council_action_family AS ENUM ('paid_media_pause','paid_media_launch','unsupported');
CREATE TABLE council_cycles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), campaign_id uuid NOT NULL REFERENCES campaigns(id), masterplan_version_id uuid NOT NULL REFERENCES masterplan_versions(id), context_fingerprint text NOT NULL, snapshot_hash text NOT NULL, owner_user_id uuid NOT NULL REFERENCES users(id), status council_cycle_status NOT NULL DEFAULT 'open', idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT council_cycle_plan_scope_fk FOREIGN KEY (workspace_id,campaign_id,masterplan_version_id) REFERENCES masterplan_versions(workspace_id,campaign_id,id));
CREATE UNIQUE INDEX council_cycles_scope_idempotency_uidx ON council_cycles(workspace_id,campaign_id,idempotency_key);
CREATE INDEX council_cycles_campaign_idx ON council_cycles(workspace_id,campaign_id,created_at);
CREATE TABLE council_minutes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), cycle_id uuid NOT NULL REFERENCES council_cycles(id), author_user_id uuid NOT NULL REFERENCES users(id), summary text NOT NULL, evidence_refs jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX council_minutes_cycle_idx ON council_minutes(workspace_id,cycle_id,created_at);
CREATE TABLE council_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), cycle_id uuid NOT NULL REFERENCES council_cycles(id), owner_user_id uuid NOT NULL REFERENCES users(id), rationale_summary text NOT NULL, evidence_refs jsonb NOT NULL DEFAULT '[]', target jsonb NOT NULL, baseline jsonb NOT NULL, threshold jsonb NOT NULL, "window" jsonb NOT NULL, due_at timestamptz, action_required boolean NOT NULL DEFAULT false, status council_decision_status NOT NULL DEFAULT 'proposed', supersedes_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX council_decisions_cycle_idx ON council_decisions(workspace_id,cycle_id,created_at);
CREATE TABLE council_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), decision_id uuid NOT NULL REFERENCES council_decisions(id), family council_action_family NOT NULL, realization_contract_id uuid REFERENCES realization_contracts(id), idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX council_actions_scope_idempotency_uidx ON council_actions(workspace_id,idempotency_key);
CREATE TABLE council_outcomes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), decision_id uuid NOT NULL REFERENCES council_decisions(id), action_id uuid REFERENCES council_actions(id), status council_outcome_status NOT NULL, verification jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX council_outcomes_decision_idx ON council_outcomes(workspace_id,decision_id,created_at);
CREATE OR REPLACE FUNCTION council_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'council records are append-only'; END $$;
CREATE TRIGGER council_minutes_append_only BEFORE UPDATE OR DELETE ON council_minutes FOR EACH ROW EXECUTE FUNCTION council_append_only();
CREATE TRIGGER council_decisions_append_only BEFORE UPDATE OR DELETE ON council_decisions FOR EACH ROW EXECUTE FUNCTION council_append_only();
CREATE TRIGGER council_actions_append_only BEFORE UPDATE OR DELETE ON council_actions FOR EACH ROW EXECUTE FUNCTION council_append_only();
CREATE TRIGGER council_outcomes_append_only BEFORE UPDATE OR DELETE ON council_outcomes FOR EACH ROW EXECUTE FUNCTION council_append_only();